from pathlib import Path

p = Path('app/src/main/java/sa/h9/qibla/MainActivity.java')
s = p.read_text(encoding='utf-8')

s = s.replace('import android.location.LocationManager;\n', 'import android.location.LocationManager;\nimport android.hardware.Sensor;\nimport android.hardware.SensorEvent;\nimport android.hardware.SensorEventListener;\nimport android.hardware.SensorManager;\nimport android.view.Surface;\n')
s = s.replace('public class MainActivity extends Activity implements LocationListener {', 'public class MainActivity extends Activity implements LocationListener, SensorEventListener {')

s = s.replace('''    private LocationManager locationManager;\n    private ConnectivityManager connectivityManager;''', '''    private LocationManager locationManager;\n    private ConnectivityManager connectivityManager;\n    private SensorManager sensorManager;\n    private Sensor rotationVectorSensor;\n    private Sensor accelerometerSensor;\n    private Sensor magneticSensor;\n    private final float[] accelValues = new float[3];\n    private final float[] magneticValues = new float[3];\n    private boolean haveAccel;\n    private boolean haveMagnetic;\n    private float lastSpeedMps;\n    private long lastGpsHeadingAt;''', 1)

s = s.replace('''        locationManager = (LocationManager) getSystemService(LOCATION_SERVICE);\n        connectivityManager = (ConnectivityManager) getSystemService(Context.CONNECTIVITY_SERVICE);''', '''        locationManager = (LocationManager) getSystemService(LOCATION_SERVICE);\n        connectivityManager = (ConnectivityManager) getSystemService(Context.CONNECTIVITY_SERVICE);\n        sensorManager = (SensorManager) getSystemService(Context.SENSOR_SERVICE);\n        if (sensorManager != null) {\n            rotationVectorSensor = sensorManager.getDefaultSensor(Sensor.TYPE_ROTATION_VECTOR);\n            accelerometerSensor = sensorManager.getDefaultSensor(Sensor.TYPE_ACCELEROMETER);\n            magneticSensor = sensorManager.getDefaultSensor(Sensor.TYPE_MAGNETIC_FIELD);\n        }''', 1)

s = s.replace('''            if (lastHeadingAt > 0 && System.currentTimeMillis() - lastHeadingAt > HEADING_STALE_MS) {\n                qiblaView.clearHeading("بانتظار اتجاه GPS حي");\n                lastHeadingAt = 0;\n                courseAnchor = null;\n            }''', '''            if (lastHeadingAt > 0 && System.currentTimeMillis() - lastHeadingAt > HEADING_STALE_MS) {\n                courseAnchor = null;\n            }''', 1)

s = s.replace('''        handler.removeCallbacks(uiTick);\n        handler.post(uiTick);\n        if (checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION) == PackageManager.PERMISSION_GRANTED) startLocation();''', '''        handler.removeCallbacks(uiTick);\n        handler.post(uiTick);\n        registerHeadingSensors();\n        if (checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION) == PackageManager.PERMISSION_GRANTED) startLocation();''', 1)

s = s.replace('''        handler.removeCallbacks(uiTick);\n        try { locationManager.removeUpdates(this); } catch (SecurityException ignored) { }''', '''        handler.removeCallbacks(uiTick);\n        if (sensorManager != null) sensorManager.unregisterListener(this);\n        try { locationManager.removeUpdates(this); } catch (SecurityException ignored) { }''', 1)

s = s.replace('''    private void updateLiveCourse(Location location) {\n        if (location.hasSpeed() && location.getSpeed() < GPS_HEADING_MIN_SPEED_MPS) {\n            qiblaView.clearHeading("وضع الوقوف: اتجاه القبلة من الشمال");\n            lastHeadingAt = 0L;\n            courseAnchor = null;\n            return;\n        }\n\n        Float newHeading = null;''', '''    private void updateLiveCourse(Location location) {\n        if (location.hasSpeed()) lastSpeedMps = location.getSpeed();\n        if (location.hasSpeed() && location.getSpeed() < GPS_HEADING_MIN_SPEED_MPS) {\n            courseAnchor = null;\n            return;\n        }\n\n        Float newHeading = null;''', 1)

s = s.replace('''            lastHeadingAt = System.currentTimeMillis();\n            qiblaView.setHeading(newHeading, "اتجاه حي عبر GPS");''', '''            lastHeadingAt = System.currentTimeMillis();\n            lastGpsHeadingAt = lastHeadingAt;\n            qiblaView.setHeading(newHeading, "اتجاه حي عبر GPS");''', 1)

marker = '    private static float circularBlend(float a, float b, float weightB) {'
methods = '''    private void registerHeadingSensors() {\n        if (sensorManager == null) return;\n        sensorManager.unregisterListener(this);\n        if (rotationVectorSensor != null) {\n            sensorManager.registerListener(this, rotationVectorSensor, SensorManager.SENSOR_DELAY_UI);\n        } else {\n            if (accelerometerSensor != null) sensorManager.registerListener(this, accelerometerSensor, SensorManager.SENSOR_DELAY_UI);\n            if (magneticSensor != null) sensorManager.registerListener(this, magneticSensor, SensorManager.SENSOR_DELAY_UI);\n        }\n    }\n\n    private float azimuthForDisplay(float[] matrix) {\n        float[] remapped = new float[9];\n        int rotation = getWindowManager().getDefaultDisplay().getRotation();\n        int x = SensorManager.AXIS_X, y = SensorManager.AXIS_Y;\n        if (rotation == Surface.ROTATION_90) { x = SensorManager.AXIS_Y; y = SensorManager.AXIS_MINUS_X; }\n        else if (rotation == Surface.ROTATION_180) { x = SensorManager.AXIS_MINUS_X; y = SensorManager.AXIS_MINUS_Y; }\n        else if (rotation == Surface.ROTATION_270) { x = SensorManager.AXIS_MINUS_Y; y = SensorManager.AXIS_X; }\n        if (!SensorManager.remapCoordinateSystem(matrix, x, y, remapped)) return Float.NaN;\n        float[] orientation = new float[3];\n        SensorManager.getOrientation(remapped, orientation);\n        return normalize((float) Math.toDegrees(orientation[0]));\n    }\n\n    private void applySensorHeading(float headingValue) {\n        if (Float.isNaN(headingValue)) return;\n        long now = System.currentTimeMillis();\n        boolean gpsFreshAndMoving = lastSpeedMps >= GPS_HEADING_MIN_SPEED_MPS && now - lastGpsHeadingAt < 3000L;\n        if (!gpsFreshAndMoving) {\n            lastHeadingAt = now;\n            qiblaView.setHeading(headingValue, "بوصلة الشاشة / الحساس");\n        }\n    }\n\n    @Override\n    public void onSensorChanged(SensorEvent event) {\n        if (event.sensor.getType() == Sensor.TYPE_ROTATION_VECTOR) {\n            float[] matrix = new float[9];\n            SensorManager.getRotationMatrixFromVector(matrix, event.values);\n            applySensorHeading(azimuthForDisplay(matrix));\n            return;\n        }\n        if (event.sensor.getType() == Sensor.TYPE_ACCELEROMETER) {\n            System.arraycopy(event.values, 0, accelValues, 0, 3);\n            haveAccel = true;\n        } else if (event.sensor.getType() == Sensor.TYPE_MAGNETIC_FIELD) {\n            System.arraycopy(event.values, 0, magneticValues, 0, 3);\n            haveMagnetic = true;\n        }\n        if (haveAccel && haveMagnetic) {\n            float[] matrix = new float[9];\n            float[] inclination = new float[9];\n            if (SensorManager.getRotationMatrix(matrix, inclination, accelValues, magneticValues)) {\n                applySensorHeading(azimuthForDisplay(matrix));\n            }\n        }\n    }\n\n    @Override public void onAccuracyChanged(Sensor sensor, int accuracy) { }\n\n'''
if 'private void registerHeadingSensors()' not in s:
    s = s.replace(marker, methods + marker, 1)

p.write_text(s, encoding='utf-8')

q = Path('app/src/main/java/sa/h9/qibla/QiblaView.java')
t = q.read_text(encoding='utf-8')
t = t.replace('c.drawText("1.4", w * .114f, h * .116f, p);', 'c.drawText("1.5", w * .114f, h * .116f, p);')
t = t.replace('"H 9   Q i b l a   1.4   •   قيادة حيّة + قبلة ثابتة عند الوقوف"', '"H 9   Q i b l a   1.5   •   GPS + حساسات + اتجاه جلسة عند الوقوف"')
t = t.replace('(hasLocation ? "وضع الوقوف: اتجاه القبلة من الشمال" : "بانتظار GPS")', '(hasLocation ? "ثابت من الشمال • تحرك قليلًا إذا لم تتوفر بوصلة" : "بانتظار GPS")')
q.write_text(t, encoding='utf-8')

g = Path('app/build.gradle')
u = g.read_text(encoding='utf-8').replace('versionCode 14', 'versionCode 15').replace("versionName '1.4'", "versionName '1.5'")
g.write_text(u, encoding='utf-8')
